from qiskit import QuantumCircuit, QuantumRegister

def solve(n: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(x, y)
    # Logarithmic-depth parity tree: fold the register onto index 0,
    # copy the accumulated parity onto y, then uncompute the tree.
    layers = []
    active = list(range(n))
    while len(active) > 1:
        layer = []
        nxt = []
        for k in range(0, len(active) - 1, 2):
            layer.append((active[k + 1], active[k]))  # (control, target)
            nxt.append(active[k])
        if len(active) % 2 == 1:
            nxt.append(active[-1])
        layers.append(layer)
        active = nxt
    for layer in layers:
        for c, t in layer:
            qc.cx(x[c], x[t])
    qc.cx(x[active[0]], y[0])
    for layer in reversed(layers):
        for c, t in layer:
            qc.cx(x[c], x[t])
    return qc

from qiskit import QuantumCircuit

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if L >= 2 ** n:
        return qc  # global phase only
    for k in range(n - 1, -1, -1):
        if (L >> k) & 1:
            # Flip states where bits above k equal L's bits, bit k is 0, lower bits arbitrary
            qubits = list(range(k, n))
            flip = []
            for q in qubits:
                if q == k:
                    flip.append(q)  # require 0
                else:
                    if not ((L >> q) & 1):
                        flip.append(q)  # require 0
            for q in flip:
                qc.x(q)
            if len(qubits) == 1:
                qc.z(qubits[0])
            else:
                target = qubits[0]
                controls = qubits[1:]
                qc.h(target)
                qc.mcx(controls, target)
                qc.h(target)
            for q in flip:
                qc.x(q)
    return qc

