def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if L >= 2 ** n:
        # All amplitudes flipped: equivalent to global phase; nothing needed
        return qc
    for i in range(L):
        zeros = [q for q in range(n) if not ((i >> q) & 1)]
        for q in zeros:
            qc.x(q)
        if n == 1:
            qc.z(0)
        else:
            target = n - 1
            controls = list(range(n - 1))
            qc.h(target)
            qc.mcx(controls, target)
            qc.h(target)
        for q in zeros:
            qc.x(q)
    return qc

from qiskit import QuantumCircuit
import numpy as np

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    N = 2 ** n
    # target phase angles: pi for x < L, 0 otherwise
    theta = np.array([np.pi if x < L else 0.0 for x in range(N)])
    # Walsh-Hadamard coefficients: theta[x] = sum_S c_S (-1)^{S.x}
    for S in range(1, N):
        c = 0.0
        for x in range(N):
            if bin(S & x).count("1") % 2 == 0:
                c += theta[x]
            else:
                c -= theta[x]
        c /= N
        if abs(c) < 1e-12:
            continue
        qubits = [q for q in range(n) if (S >> q) & 1]
        target = qubits[-1]
        others = qubits[:-1]
        for q in others:
            qc.cx(q, target)
        qc.rz(-2 * c, target)
        for q in reversed(others):
            qc.cx(q, target)
    return qc

