from qiskit.circuit.library import ZGate

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if L >= 2 ** n:
        # Flipping every amplitude is just a global phase
        return qc
    for k in range(n):
        if (L >> k) & 1:
            # Flip all states whose bits above k match L and whose bit k is 0
            qubits = list(range(k, n))
            flip = [k] + [j for j in range(k + 1, n) if not ((L >> j) & 1)]
            for q in flip:
                qc.x(q)
            if len(qubits) == 1:
                qc.z(qubits[0])
            else:
                qc.append(ZGate().control(len(qubits) - 1), qubits)
            for q in flip:
                qc.x(q)
    return qc

