def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    N = 1 << n

    if L >= N:
        # every amplitude flipped -> global phase only
        return qc

    # bit j of the integer lives on wire n-1-j
    def wire(j: int) -> int:
        return n - 1 - j

    for k in range(n):
        if not (L >> k) & 1:
            continue
        # target block: bit k == 0 and all higher bits equal those of L
        zeros = [k] + [j for j in range(k + 1, n) if not (L >> j) & 1]
        qs = [wire(j) for j in range(k, n)]

        for j in zeros:
            qc.x(wire(j))

        if len(qs) == 1:
            qc.z(qs[0])
        else:
            qc.mcp(pi, qs[:-1], qs[-1])

        for j in zeros:
            qc.x(wire(j))

    return qc

