def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    qc.x(0)
    qc.h(0)
    # log-depth fan-out of CNOTs
    filled = 1
    while filled < n:
        for i in range(filled):
            if i + filled < n:
                qc.cx(i, i + filled)
        filled *= 2
    return qc

from qiskit import QuantumCircuit

def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    qc.h(0)
    prepared = 1
    last_used = {0}
    while prepared < n:
        count = min(prepared, n - prepared)
        last_used = set()
        for i in range(count):
            qc.cx(i, prepared + i)
            last_used.add(i)
            last_used.add(prepared + i)
        prepared += count
    idle = [q for q in range(n) if q not in last_used]
    if idle:
        qc.z(idle[0])
    else:
        qc.z(0)
    return qc

