from qiskit.circuit.library import PhaseGate

def solve(n: int, L: int, theta: float) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # Flip qubits whose bit in L is 0 so that |L> -> |11...1>
    for i in range(n):
        if not ((L >> i) & 1):
            qc.x(i)
    # Apply phase theta to |11...1>
    if n == 1:
        qc.p(theta, 0)
    else:
        gate = PhaseGate(theta).control(n - 1)
        qc.append(gate, list(range(n)))
    # Unflip
    for i in range(n):
        if not ((L >> i) & 1):
            qc.x(i)
    return qc

