def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # Decompose each coefficient S_i into its binary digits and apply, for each set
    # bit j, a phase of 2*pi*2^j/2^m = pi/2^(m-1-j). Use exact Z/S/T gates where possible.
    for j in range(m):
        k = m - 1 - j  # angle is pi / 2^k
        for i in range(n):
            if (S[i] >> j) & 1:
                if k == 0:
                    qc.z(i)
                elif k == 1:
                    qc.s(i)
                elif k == 2:
                    qc.t(i)
                else:
                    qc.p(math.pi / (2 ** k), i)
    return qc

