def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    # Build a depth-optimized QFT (no swaps) on register y.
    # Position p ends up holding output bit k_{m-1-p}.
    qft = QuantumCircuit(y)
    T = 2 * m - 1
    layers = [[] for _ in range(T)]
    for j in range(m):
        layers[2 * (m - 1 - j)].append(('h', j))
        for k in range(j):
            layers[2 * m - 2 - j - k].append(('cp', k, j))
    for layer in layers:
        for g in layer:
            if g[0] == 'h':
                qft.h(y[g[1]])
            else:
                k, j = g[1], g[2]
                qft.cp(pi / 2 ** (j - k), y[k], y[j])

    qc.compose(qft, y, inplace=True)

    # Controlled phase additions, scheduled as matchings for low depth.
    L = max(n, m)
    for r in range(L):
        for i in range(n):
            p = (i + r) % L
            if p < m:
                c = S[i] % (2 ** m)
                if c != 0:
                    qc.cp(pi * c / 2 ** p, x[i], y[p])

    qc.compose(qft.inverse(), y, inplace=True)

    return qc

