def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    # Prepare y in uniform superposition (QFT of |0>).
    for q in range(m):
        qc.h(y[q])

    # Phase kickback: qubit y[q] acquires phase exp(2*pi*i * f / 2^(q+1)).
    L = max(n, m)
    for r in range(L):
        for i in range(n):
            q = (i + r) % L
            if q < m:
                c = S[i] % (2 ** (q + 1))
                if c != 0:
                    qc.cp(pi * c / (2 ** q), x[i], y[q])

    # Decode: semiclassical inverse-QFT-like stage, y[q] ends holding f_q.
    T = 2 * m - 1
    layers = [[] for _ in range(T)]
    for q in range(m):
        layers[2 * q].append(('h', q))
        for j in range(q):
            layers[j + q].append(('cp', j, q))
    for layer in layers:
        for g in layer:
            if g[0] == 'h':
                qc.h(y[g[1]])
            else:
                j, q = g[1], g[2]
                qc.cp(-pi / (2 ** (q - j)), y[j], y[q])

    return qc

