def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    # QFT on y (no swaps): qubit j ends up holding z_{m-1-j}
    def qft(circ):
        for j in reversed(range(m)):
            circ.h(y[j])
            for k in reversed(range(j)):
                circ.cp(pi / 2 ** (j - k), y[k], y[j])

    def iqft(circ):
        for j in range(m):
            for k in range(j):
                circ.cp(-pi / 2 ** (j - k), y[k], y[j])
            circ.h(y[j])

    qft(qc)

    # Controlled phase additions, scheduled in max(n, m) layers
    L = max(n, m)
    for r in range(L):
        for i in range(n):
            k = (i + r) % L
            if k < m:
                # phase 2*pi*S_i*2^{m-1-k}/2^m = pi*S_i/2^k
                val = (S[i] * (2 ** (m - 1 - k))) % (2 ** m)
                if val == 0:
                    continue
                ang = 2 * pi * val / (2 ** m)
                qc.cp(ang, x[i], y[k])

    iqft(qc)

    return qc

