def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)
    # Write your code here:

    # Controlled-phase gates are realised as crz + a single-qubit rz correction
    # on the control (cp(phi) = crz(phi) * rz(phi/2) on control, up to global phase).
    # All rz corrections on a given qubit are accumulated and applied in one layer
    # at a time when that qubit is in the computational basis.
    pre_y = [0.0] * m
    pre_x = [0.0] * n
    post_y = [0.0] * m

    # Corrections for the forward / inverse Fourier transforms.
    for j in range(m):
        for k in range(j):
            phi = pi / (1 << (j - k))
            pre_y[k] += phi / 2.0
            post_y[k] -= phi / 2.0

    # Corrections for the phase-domain addition (controls are x qubits).
    for i in range(n):
        for j in range(m):
            period = 1 << (j + 1)
            v = S[i] % period
            if v:
                pre_x[i] += (2.0 * pi * v / period) / 2.0

    # Pre-corrections (y still in computational basis, x never changes).
    for k in range(m):
        if pre_y[k] != 0.0:
            qc.rz(pre_y[k], y[k])
    for i in range(n):
        if pre_x[i] != 0.0:
            qc.rz(pre_x[i], x[i])

    # Forward Fourier transform on y (no swaps).
    for j in reversed(range(m)):
        qc.h(y[j])
        for k in reversed(range(j)):
            qc.crz(pi / (1 << (j - k)), y[k], y[j])

    # Phase-domain addition of f(x), scheduled round-robin.
    L = max(n, m)
    for r in range(L):
        for i in range(n):
            k = (i + r) % L
            if k >= m:
                continue
            j = m - 1 - k
            period = 1 << (j + 1)
            v = S[i] % period
            if v == 0:
                continue
            qc.crz(2.0 * pi * v / period, x[i], y[j])

    # Inverse Fourier transform on y.
    for j in range(m):
        for k in range(j):
            qc.crz(-pi / (1 << (j - k)), y[k], y[j])
        qc.h(y[j])

    # Post-corrections (y back in computational basis).
    for k in range(m):
        if post_y[k] != 0.0:
            qc.rz(post_y[k], y[k])

    return qc

