def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)
    M = 1 << m

    def diag(qubits, phi):
        # apply diag(e^{i phi[z]}) up to global phase using parity (Walsh) decomposition
        k = len(qubits)
        K = 1 << k
        c = [0.0] * K
        for T in range(1, K):
            s = 0.0
            for z in range(K):
                if phi[z] != 0:
                    if bin(z & T).count('1') % 2 == 0:
                        s += phi[z]
                    else:
                        s -= phi[z]
            c[T] = s / K
        for t in range(k - 1, -1, -1):
            others = list(range(t))
            tmask = 1 << t
            prev = 0
            if abs(c[tmask]) > 1e-12:
                qc.rz(-2 * c[tmask], qubits[t])
            for i in range(1, 1 << len(others)):
                g = i ^ (i >> 1)
                b = (g ^ prev).bit_length() - 1
                qc.cx(qubits[others[b]], qubits[t])
                prev = g
                if abs(c[tmask | g]) > 1e-12:
                    qc.rz(-2 * c[tmask | g], qubits[t])
            if others:
                b = prev.bit_length() - 1
                qc.cx(qubits[others[b]], qubits[t])

    if n <= 5:
        phi = []
        for z in range(1 << n):
            f = 0
            for i in range(n):
                if (z >> i) & 1:
                    f += S[i]
            phi.append(theta if (f % M) == L else 0.0)
        diag(list(x), phi)
    else:
        N = max(n, m)

        def phases(sign):
            for r in range(N):
                for j in range(n):
                    l = (r - j) % N
                    if l < m:
                        a = (S[j] * (1 << l)) % M
                        if a:
                            qc.cp(sign * 2 * math.pi * a / M, x[j], y[l])
            for l in range(m):
                a = (L * (1 << l)) % M
                if a:
                    qc.p(-sign * 2 * math.pi * a / M, y[l])

        qc.h(y)
        phases(1)
        qc.h(y)
        phi = [theta] + [0.0] * (M - 1)
        diag(list(y), phi)
        qc.h(y)
        phases(-1)
        qc.h(y)

    return qc

