"""
You can apply U and R as follows:
qc.compose(U(), inplace=True)
qc.compose(R(theta), inplace=True)
"""


def solve(n: int, P: float, U, R) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    def apply_op(op):
        if isinstance(op, QuantumCircuit):
            qc.compose(op, inplace=True)
        else:
            qc.append(op, list(range(n)))

    def apply_U():
        apply_op(U())

    def apply_Udg():
        apply_op(U().inverse())

    def apply_Ss(alpha):
        # I - (1 - e^{-i alpha}) |0><0|
        for q in range(n):
            qc.x(q)
        if n == 1:
            qc.p(-alpha, 0)
        else:
            qc.mcp(-alpha, list(range(n - 1)), n - 1)
        for q in range(n):
            qc.x(q)

    if P >= 0.995:
        apply_U()
        return qc

    delta = 0.08
    inv_delta = 1.0 / delta
    lam_min = min(max(P, 1e-6), 0.995)
    L_real = math.acosh(inv_delta) / math.acosh(1.0 / math.sqrt(1.0 - lam_min))
    L = int(math.ceil(L_real))
    if L % 2 == 0:
        L += 1
    if L < 3:
        L = 3
    l = (L - 1) // 2

    gamma_inv = math.cosh(math.acosh(inv_delta) / L)
    gamma2 = 1.0 / (gamma_inv ** 2)
    s = math.sqrt(max(0.0, 1.0 - gamma2))

    def acot(x):
        return math.pi / 2 - math.atan(x)

    alphas = [2.0 * acot(math.tan(2.0 * math.pi * j / L) * s) for j in range(1, l + 1)]
    betas = [-alphas[l - j] for j in range(1, l + 1)]

    apply_U()
    for j in range(l):
        qc.compose(R(betas[j]), inplace=True)
        apply_Udg()
        apply_Ss(alphas[j])
        apply_U()

    return qc

