    delta = 0.05
    lam = min(max(P, 1e-9), 1.0)

    # find smallest odd L such that lam >= 1 - gamma^2, gamma^{-1} = T_{1/L}(1/delta)
    L = 1
    while True:
        gamma_inv = math.cosh(math.acosh(1.0 / delta) / L)
        gamma2 = 1.0 / (gamma_inv * gamma_inv)
        if lam >= 1.0 - gamma2 - 1e-12:
            break
        L += 2
        if L > 199:
            break
    l = (L - 1) // 2

    if l == 0:
        add_U()
        return qc

    s = math.sqrt(max(0.0, 1.0 - gamma2))

    def acot(x):
        return math.atan2(1.0, x)

    def wrap(a):
        while a > math.pi:
            a -= 2 * math.pi
        while a <= -math.pi:
            a += 2 * math.pi
        return a

    alphas = [wrap(2.0 * acot(math.tan(2.0 * math.pi * j / L) * s)) for j in range(1, l + 1)]

    add_U()
    for j in range(l):
        a = alphas[j]
        # S_t(beta_j) with beta_j = alpha_j ; R(theta) = S_t(-theta)
        qc.compose(R(-a), inplace=True)
        # S_s(alpha_j) = U S_0(alpha_j) U^dagger
        add_Udg()
        add_S0(a)
        add_U()

    return qc

import math
from qiskit import QuantumCircuit

"""
You can apply U and R as follows:
qc.compose(U(), inplace=True)
qc.compose(R(theta), inplace=True)
"""


def solve(n: int, P: float, U, R) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    qubits = list(range(n))

    U_op = U()
    Udg_op = U_op.inverse()

    def app(c, op):
        if isinstance(op, QuantumCircuit):
            c.compose(op, inplace=True)
        else:
            c.append(op, qubits)

    def app_U(c):
        app(c, U_op)

    def app_Udg(c):
        app(c, Udg_op)

    def app_R(c, theta):
        app(c, R(theta))

    def app_S0(c, phi):
        # I - (1 - e^{i phi}) |0..0><0..0|
        for q in qubits:
            c.x(q)
        if n == 1:
            c.p(phi, 0)
        else:
            c.mcp(phi, qubits[:-1], qubits[-1])
        for q in qubits:
            c.x(q)

    # ---- choose k (standard Grover iterations) and m (pi/3 recursion depth) ----
    Pc = min(max(P, 1e-12), 1.0)
    th_lo = math.asin(math.sqrt(Pc))
    th_hi = math.asin(math.sqrt(min(1.0, 4.0 * Pc)))

    best = None  # (calls, fail, k, m)
    for k in range(0, 60):
        a = (2 * k + 1) * th_lo
        b = (2 * k + 1) * th_hi
        if b > math.pi + 1e-12:
            break
        q = min(math.sin(a) ** 2, math.sin(b) ** 2)
        eps = max(0.0, 1.0 - q)
        for m in range(0, 6):
            fail = eps ** (3 ** m)
            calls = k * (3 ** m) + (3 ** m - 1) // 2
            if calls > 100:
                break
            if fail <= 0.003:
                cand = (calls, fail, k, m)
                if best is None or cand[0] < best[0] or (cand[0] == best[0] and cand[1] < best[1]):
                    best = cand
                break
    if best is None:
        # fallback: pick something reasonable
        bestf = None
        for k in range(0, 60):
            a = (2 * k + 1) * th_lo
            b = (2 * k + 1) * th_hi
            if b > math.pi + 1e-12:
                break
            q = min(math.sin(a) ** 2, math.sin(b) ** 2)
            eps = max(0.0, 1.0 - q)
            for m in range(0, 6):
                calls = k * (3 ** m) + (3 ** m - 1) // 2
                if calls > 100:
                    break
                fail = eps ** (3 ** m)
                cand = (fail, calls, k, m)
                if bestf is None or cand < bestf:
                    bestf = cand
        if bestf is None:
            k_sel, m_sel = 0, 3
        else:
            k_sel, m_sel = bestf[2], bestf[3]
    else:
        k_sel, m_sel = best[2], best[3]

    # ---- A' = G^k U ----
    def build_Aprime(dagger):
        c = QuantumCircuit(n)
        if not dagger:
            app_U(c)
            for _ in range(k_sel):
                app_R(c, math.pi)
                app_Udg(c)
                app_S0(c, math.pi)
                app_U(c)
        else:
            for _ in range(k_sel):
                app_Udg(c)
                app_S0(c, -math.pi)
                app_U(c)
                app_R(c, -math.pi)
            app_Udg(c)
        return c

    cache = {}

    def build_V(m, dagger):
        key = (m, dagger)
        if key in cache:
            return cache[key]
        if m == 0:
            c = build_Aprime(dagger)
        else:
            V = build_V(m - 1, False)
            Vd = build_V(m - 1, True)
            c = QuantumCircuit(n)
            if not dagger:
                c.compose(V, inplace=True)
                app_R(c, math.pi / 3)
                c.compose(Vd, inplace=True)
                app_S0(c, math.pi / 3)
                c.compose(V, inplace=True)
            else:
                c.compose(Vd, inplace=True)
                app_S0(c, -math.pi / 3)
                c.compose(V, inplace=True)
                app_R(c, -math.pi / 3)
                c.compose(Vd, inplace=True)
        cache[key] = c
        return c

    final = build_V(m_sel, False)
    qc.compose(final, inplace=True)
    return qc

import math
import numpy as np
from qiskit import QuantumCircuit
from qiskit.quantum_info import Operator, Statevector
from qiskit.circuit.library import UnitaryGate

"""
You can apply U and R as follows:
qc.compose(U(), inplace=True)
qc.compose(R(theta), inplace=True)
"""


def solve(n: int, P: float, U, R) -> QuantumCircuit:
    qubits = list(range(n))
    TWO_PI = 2.0 * math.pi

    def to_circ(op):
        if isinstance(op, QuantumCircuit):
            return op
        c = QuantumCircuit(n)
        c.append(op, qubits)
        return c

    U_circ = to_circ(U())
    Udg_circ = None
    try:
        Udg_circ = U_circ.inverse()
    except Exception:
        Udg_circ = None
    if Udg_circ is None:
        try:
            Udg_circ = QuantumCircuit(n)
            Udg_circ.append(UnitaryGate(Operator(U_circ).adjoint()), qubits)
        except Exception:
            Udg_circ = U_circ.inverse()

    # ---------- basic-gate decompositions (no mcp / mcx) ----------
    def ccx_(c, a, b, t):
        c.h(t); c.cx(b, t); c.tdg(t); c.cx(a, t); c.t(t); c.cx(b, t); c.tdg(t); c.cx(a, t)
        c.t(b); c.t(t); c.h(t); c.cx(a, b); c.t(a); c.tdg(b); c.cx(a, b)

    def mcx_(c, controls, t):
        k = len(controls)
        if k == 0:
            c.x(t)
        elif k == 1:
            c.cx(controls[0], t)
        elif k == 2:
            ccx_(c, controls[0], controls[1], t)
        else:
            c.h(t)
            mcp_(c, math.pi, controls, t)
            c.h(t)

    def mcp_(c, phi, controls, t):
        k = len(controls)
        if k == 0:
            c.p(phi, t)
        elif k == 1:
            c.cp(phi, controls[0], t)
        else:
            last = controls[-1]
            rest = controls[:-1]
            c.cp(phi / 2.0, last, t)
            mcx_(c, rest, last)
            c.cp(-phi / 2.0, last, t)
            mcx_(c, rest, last)
            mcp_(c, phi / 2.0, rest, t)

    def add_S0(c, phi):
        # I - (1 - e^{i phi}) |0..0><0..0|
        for q in qubits:
            c.x(q)
        if n == 1:
            c.p(phi, 0)
        else:
            mcp_(c, phi, qubits[:-1], qubits[-1])
        for q in qubits:
            c.x(q)

    def add_R(c, theta):
        th = theta % TWO_PI
        c.compose(to_circ(R(th)), inplace=True)

    def build(th_seq, al_seq):
        c = QuantumCircuit(n)
        c.compose(U_circ, inplace=True)
        for th, al in zip(th_seq, al_seq):
            add_R(c, th)
            # S_s(alpha) = I - (1 - e^{-i alpha})|s><s| = U S0(-alpha) U^dagger
            c.compose(Udg_circ, inplace=True)
            add_S0(c, -al)
            c.compose(U_circ, inplace=True)
        return c

    # ---------- 2D classical model ----------
    def success(lam, thetas, alphas):
        a = math.sqrt(lam)
        b = math.sqrt(max(0.0, 1.0 - lam))
        v0 = complex(a)
        v1 = complex(b)
        for th, al in zip(thetas, alphas):
            v0 = v0 * complex(math.cos(th), math.sin(th))
            inner = a * v0 + b * v1
            f = (1.0 - complex(math.cos(al), -math.sin(al))) * inner
            v0 = v0 - f * a
            v1 = v1 - f * b
        return abs(v0) ** 2

    Pc = min(max(P, 1e-9), 1.0)
    lam_hi = min(4.0 * Pc, 1.0)
    grid = np.linspace(Pc, lam_hi, 161)

    def min_success(th, al):
        return min(success(float(l), th, al) for l in grid)

    target = 0.993
    delta = 0.07
    Pp = min(0.95 * Pc, 0.999)
    base = math.acosh(1.0 / math.sqrt(1.0 - Pp))
    L0 = int(math.ceil(math.acosh(1.0 / delta) / base))
    if L0 % 2 == 0:
        L0 += 1
    if L0 < 1:
        L0 = 1

    def acot(x):
        return math.atan2(1.0, x)

    def ylc_candidates(L):
        l = (L - 1) // 2
        if l == 0:
            return [([], [])]
        gamma_inv = math.cosh(math.acosh(1.0 / delta) / L)
        s = math.sqrt(max(0.0, 1.0 - 1.0 / (gamma_inv * gamma_inv)))
        alphas = [2.0 * acot(math.tan(2.0 * math.pi * j / L) * s) for j in range(1, l + 1)]
        rev = alphas[::-1]
        main_th = [-x for x in rev]  # beta_j = -alpha_{l-j+1}
        cands = [(main_th, alphas)]
        for al_seq in (alphas, rev):
            for th_seq in ([-x for x in rev], [-x for x in alphas], list(rev), list(alphas)):
                cands.append((th_seq, al_seq))
        return cands

    chosen = None
    best = None
    all_cands = []
    Ls = [1] if Pc >= target else []
    L = L0
    while len(Ls) < 8 and L <= 201:
        Ls.append(L)
        L += 2
    for L in Ls:
        for th_seq, al_seq in ylc_candidates(L):
            all_cands.append((th_seq, al_seq))
            ms = min_success(th_seq, al_seq)
            if best is None or ms > best[0]:
                best = (ms, th_seq, al_seq)
            if ms >= target and chosen is None:
                chosen = (th_seq, al_seq)
        if chosen is not None:
            break
    if chosen is None:
        chosen = (best[1], best[2])

    qc = build(chosen[0], chosen[1])

    # ---------- optional verification with real gates (convention independent) ----------
    try:
        Rm = np.array(Operator(to_circ(R(math.pi))).data, dtype=complex)
        dim = 2 ** n
        Pw = (np.eye(dim, dtype=complex) - Rm) / 2.0
        idx = int(np.argmax(np.linalg.norm(Pw, axis=0)))
        w = Pw[:, idx]
        w = w / np.linalg.norm(w)
        if np.allclose(Pw, np.outer(w, w.conj()), atol=1e-6):
            sv = Statevector(qc).data
            fid = abs(np.vdot(w, sv)) ** 2
            if fid < 0.99:
                best_alt = (fid, qc)
                seen = 0
                for th_seq, al_seq in all_cands:
                    if len(th_seq) > 100 or seen >= 8:
                        break
                    seen += 1
                    c2 = build(th_seq, al_seq)
                    f2 = abs(np.vdot(w, Statevector(c2).data)) ** 2
                    if f2 > best_alt[0]:
                        best_alt = (f2, c2)
                    if f2 >= 0.995:
                        break
                qc = best_alt[1]
    except Exception:
        pass

    return qc

