import math


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    # Sequential conditional preparation with open controls:
    # qubit i becomes 1 with probability 1/(n-i) given all previous qubits are 0.
    for i in range(n - 1):
        theta = 2 * math.asin(math.sqrt(1.0 / (n - i)))
        if i == 0:
            qc.ry(theta, 0)
        else:
            controls = list(range(i))
            for c in controls:
                qc.x(c)
            qc.mcry(theta, controls, i)
            for c in controls:
                qc.x(c)

    # Last qubit: set to 1 if all previous qubits are 0
    controls = list(range(n - 1))
    for c in controls:
        qc.x(c)
    qc.mcx(controls, n - 1)
    for c in controls:
        qc.x(c)

    return qc

