import numpy as np


def _mcphase(qc: QuantumCircuit, theta: float, controls, target):
    k = len(controls)
    if k == 0:
        qc.p(theta, target)
        return
    if k == 1:
        qc.cp(theta, controls[0], target)
        return
    lam = theta / (2 ** (k - 1))
    gray = [format(i ^ (i >> 1), "0{}b".format(k)) for i in range(2 ** k)]
    last = None
    for pattern in gray:
        if "1" not in pattern:
            continue
        if last is None:
            last = pattern
        lm = pattern.index("1")
        comp = [a != b for a, b in zip(pattern, last)]
        pos = comp.index(True) if True in comp else None
        if pos is not None:
            if pos != lm:
                qc.cx(controls[pos], controls[lm])
            else:
                idxs = [i for i, ch in enumerate(pattern) if ch == "1"]
                for idx in idxs[1:]:
                    qc.cx(controls[idx], controls[lm])
        if pattern.count("1") % 2 == 0:
            qc.cp(-lam, controls[lm], target)
        else:
            qc.cp(lam, controls[lm], target)
        last = pattern


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # Write your code here:
    # A = H^n (2|0><0| - I) H^n ; 2|0><0| - I ~ X^n (C^{n-1}Z) X^n up to global phase
    qc.h(range(n))
    qc.x(range(n))
    _mcphase(qc, np.pi, list(range(n - 1)), n - 1)
    qc.x(range(n))
    qc.h(range(n))
    return qc

