import numpy as np


def _mcz_all(qc: QuantumCircuit, n: int):
    # Apply phase (-1)^{x_0 x_1 ... x_{n-1}} using the identity
    # x_0...x_{n-1} = (1/2^{n-1}) * sum_{S nonempty} (-1)^{|S|+1} parity_S(x)
    base = np.pi / (2 ** (n - 1))
    for mask in range(1, 2 ** n):
        members = [i for i in range(n) if (mask >> i) & 1]
        t = members[0]
        others = members[1:]
        for o in others:
            qc.cx(o, t)
        sign = 1.0 if (len(members) % 2 == 1) else -1.0
        qc.p(sign * base, t)
        for o in reversed(others):
            qc.cx(o, t)


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # Write your code here:
    # A = H^n (2|0><0| - I) H^n ; 2|0><0| - I = -(X^n MCZ X^n)
    for q in range(n):
        qc.h(q)
    for q in range(n):
        qc.x(q)
    _mcz_all(qc, n)
    for q in range(n):
        qc.x(q)
    for q in range(n):
        qc.h(q)
    return qc

