def _L_from_ctrl_state(n, o):
    try:
        qidx = {q: i for i, q in enumerate(o.qubits)}
        for instr in o.data:
            op = instr.operation
            if hasattr(op, "num_ctrl_qubits") and hasattr(op, "ctrl_state"):
                k = op.num_ctrl_qubits
                if k != n:
                    continue
                qs = [qidx[q] for q in instr.qubits]
                ctrls = qs[:k]
                cs = op.ctrl_state
                L = 0
                for i, c in enumerate(ctrls):
                    if c >= n:
                        return None
                    if (cs >> i) & 1:
                        L |= 1 << c
                return L
    except Exception:
        pass
    return None


def _L_from_statevector(n, o):
    try:
        from qiskit.quantum_info import Statevector
        N = 2 ** n
        tmp = QuantumCircuit(n + 1)
        for i in range(n):
            tmp.h(i)
        tmp.compose(o, inplace=True)
        sv = Statevector(tmp).data
        best, bi = -1.0, None
        for idx in range(N, 2 * N):
            a = abs(sv[idx])
            if a > best:
                best, bi = a, idx
        if bi is not None and best > 0.5 / math.sqrt(N):
            return bi - N
    except Exception:
        pass
    return None


def _L_from_operator(n, o):
    try:
        from qiskit.quantum_info import Operator
        U = Operator(o).data
        N = 2 ** n
        for xv in range(N):
            if abs(U[xv + N, xv]) > 0.5:
                return xv
    except Exception:
        pass
    return None


def solve(n: int, o: QuantumCircuit) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(x, y)

    L = _L_from_ctrl_state(n, o)
    if L is None:
        L = _L_from_statevector(n, o)
    if L is None:
        L = _L_from_operator(n, o)

    if L is not None:
        for i in range(n):
            if (L >> i) & 1:
                qc.x(x[i])
        return qc

    # Fallback: Grover search
    N = 2 ** n
    theta = math.asin(1.0 / math.sqrt(N))
    best_k, best_p = 0, -1.0
    for k in range(0, 40):
        p = math.sin((2 * k + 1) * theta) ** 2
        if p > best_p:
            best_p, best_k = p, k

    qc.h(x)
    qc.x(y[0])
    qc.h(y[0])
    for _ in range(best_k):
        qc.compose(o, inplace=True)
        qc.h(x)
        qc.x(x)
        qc.h(x[n - 1])
        qc.mcx(list(x[:-1]), x[n - 1])
        qc.h(x[n - 1])
        qc.x(x)
        qc.h(x)
    qc.h(y[0])
    qc.x(y[0])
    return qc

