def solve(n: int, a: int) -> QuantumCircuit:
    k, c = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(k, c)
    # Write your code here:
    N = 2 ** n

    # Build QFT circuit on the k register (little-endian: k[j] has weight 2^j)
    qft = QuantumCircuit(k)
    for i in range(n - 1, -1, -1):
        qft.h(k[i])
        for m in range(i - 1, -1, -1):
            qft.cp(math.pi / (2 ** (i - m)), k[m], k[i])
    for i in range(n // 2):
        qft.swap(k[i], k[n - 1 - i])

    # O = QFT * C-ADD(a) * QFT^dagger
    qc.compose(qft.inverse(), qubits=list(k), inplace=True)

    # Controlled addition of a (mod 2^n), controlled on c
    a_mod = a % N
    for i in range(n):
        if (a_mod >> i) & 1:
            # controlled add 2^i: increment on bits i..n-1
            for j in range(n - 1, i - 1, -1):
                controls = [c[0]] + [k[t] for t in range(i, j)]
                if len(controls) == 1:
                    qc.cx(controls[0], k[j])
                else:
                    qc.mcx(controls, k[j])

    qc.compose(qft, qubits=list(k), inplace=True)

    return qc

