def solve(n: int, a: int) -> QuantumCircuit:
    k, c = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(k, c)

    a %= (1 << n)
    if a == 0:
        return qc

    # Forward QFT without final swaps (qubit j ends up holding bit n-1-j of y)
    for j in reversed(range(n)):
        qc.h(k[j])
        for m in range(j):
            qc.cp(pi / (2 ** (j - m)), k[m], k[j])

    # Controlled phase addition of a: bit t of y lives on qubit n-1-t
    for t in range(n):
        angle = 2 * pi * ((a * (1 << t)) % (1 << n)) / (1 << n)
        if angle != 0.0:
            qc.cp(angle, c[0], k[n - 1 - t])

    # Inverse QFT without swaps
    for j in range(n):
        for m in reversed(range(j)):
            qc.cp(-pi / (2 ** (j - m)), k[m], k[j])
        qc.h(k[j])

    return qc

