from math import pi


def solve(n: int, a: int) -> QuantumCircuit:
    k, c = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(k, c)

    a %= (1 << n)
    if a == 0:
        return qc

    def cphase(theta, q1, q2):
        # controlled phase decomposed into p and cx gates
        qc.p(theta / 2, q1)
        qc.p(theta / 2, q2)
        qc.cx(q1, q2)
        qc.p(-theta / 2, q2)
        qc.cx(q1, q2)

    def swap(q1, q2):
        qc.cx(q1, q2)
        qc.cx(q2, q1)
        qc.cx(q1, q2)

    def qft():
        for i in reversed(range(n)):
            qc.h(k[i])
            for j in range(i):
