def solve(n: int, s: int, t: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    N = 1 << n

    def apply_mcx(controls, target):
        controls = list(controls)
        if len(controls) == 0:
            qc.x(target)
        elif len(controls) == 1:
            qc.cx(controls[0], target)
        elif len(controls) == 2:
            qc.ccx(controls[0], controls[1], target)
        else:
            qc.mcx(controls, target)

    def subtract_const(c, extra):
        # Borrow-lookahead subtraction of constant c (mod 2^n) on qubits 0..n-1.
        # y_i = x_i XOR c_i XOR [ (x mod 2^i) < (c mod 2^i) ], processed from high bit to low bit.
        c %= N
        if c == 0:
            return
        for i in range(n - 1, -1, -1):
            L = c & ((1 << i) - 1)
            # borrow into bit i: (x mod 2^i) < L, decomposed into dyadic intervals
            for p in range(i - 1, -1, -1):
                if (L >> p) & 1:
                    zeros = [p] + [q for q in range(p + 1, i) if not ((L >> q) & 1)]
                    for q in zeros:
                        qc.x(q)
                    apply_mcx(list(range(p, i)) + list(extra), i)
                    for q in zeros:
                        qc.x(q)
            # constant bit
            if (c >> i) & 1:
                apply_mcx(list(extra), i)

    # Unconditionally subtract s from the lower n bits
    subtract_const(s, [])

    # If MSB (qubit n) is set, subtract an additional (t - 2^n - s) so total is (t - 2^n)
    m = t - N
    subtract_const((m - s) % N, [n])

    return qc

