def solve(n: int, a: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    flag = n

    def less_than(c):
        # flag ^= [value(low) < c]  (value(low) < 2^n)
        if c <= 0:
            return
        if c >= (1 << n):
            qc.x(flag)
            return
        for i in range(n):
            if (c >> i) & 1:
                flips = [i] + [j for j in range(i + 1, n) if not ((c >> j) & 1)]
                for q in flips:
                    qc.x(q)
                qc.mcx(list(range(i, n)), flag)
                for q in flips:
                    qc.x(q)

    def qft_noswap():
        for j in reversed(range(n)):
            qc.h(j)
            for l in range(j):
                qc.cp(math.pi / (2 ** (j - l)), l, j)

    def iqft_noswap():
        for j in range(n):
            for l in reversed(range(j)):
                qc.cp(-math.pi / (2 ** (j - l)), l, j)
            qc.h(j)

    # Step 1: flag = [k + a < L]  (i.e. no wrap-around)
    less_than(L - a)

    # Step 2: low += (a - L) mod 2^n ; if flag: low += L
    # After QFT without swaps, qubit j carries weight 2^(n-1-j)
    qft_noswap()
    c1 = (a - L) % (1 << n)
    for j in range(n):
        ang = math.pi * c1 / (2 ** j)
        if ang % (2 * math.pi) != 0:
            qc.p(ang, j)
    c2 = L % (1 << n)
    for j in range(n):
        ang = math.pi * c2 / (2 ** j)
        if ang % (2 * math.pi) != 0:
            qc.cp(ang, flag, j)
    iqft_noswap()

    # Step 3: uncompute flag. result r: flag==1 iff r >= a
    less_than(a)
    qc.x(flag)

    return qc

