def solve(a: int, L: int) -> int:
    result: int = 0
    # Write your code here:
    # Binary (Stein-style) extended GCD for modular inverse.
    # Works for odd modulus directly; for even modulus, invert the modulus
    # modulo a (which must then be odd) and recover the answer algebraically.

    def half_mod(x: int, m: int) -> int:
        # returns x/2 mod m for odd m
        if x & 1:
            x += m
        return x >> 1

    def binary_inverse_odd(x: int, m: int) -> int:
        # inverse of x modulo odd m, assumes gcd(x, m) == 1, 0 < x < m
        u, v = x, m
        x1, x2 = 1, 0
        while u != 1 and v != 1:
            if u == 0 or v == 0:
                break
            while (u & 1) == 0:
                u >>= 1
                x1 = half_mod(x1, m)
            while (v & 1) == 0:
                v >>= 1
                x2 = half_mod(x2, m)
            if u >= v:
                u -= v
                x1 -= x2
            else:
                v -= u
                x2 -= x1
        if u == 1:
            return x1 % m
        elif v == 1:
            return x2 % m
        return 0

    if L <= 1:
        result = 0
    else:
        aa = a % L
        if aa == 0:
            result = 0
        elif aa == 1:
            result = 1
        elif L & 1:
            result = binary_inverse_odd(aa, L)
        else:
            # L is even, so aa must be odd (coprime).
            lm = L % aa
            if aa == 1:
                y = 0
            elif lm == 0:
                y = 0
            else:
                y = binary_inverse_odd(lm, aa)
            # L*y ≡ 1 (mod aa)  =>  1 - L*y = aa * x  =>  aa*x ≡ 1 (mod L)
            num = 1 - L * y
            if num % aa == 0:
                result = (num // aa) % L
            else:
                result = 0

    return result

