    def transposition(ctrl, u, v):
        # swap basis states |u> and |v> of the low n qubits of y, controlled on ctrl
        d = u ^ v
        p = 0
        while not (d >> p) & 1:
            p += 1
        others = [q for q in range(n) if q != p and (d >> q) & 1]
        for q in others:
