                continue
            bit = (u >> q) & 1
            if (d >> q) & 1:
                bit ^= (u >> p) & 1
            pattern[q] = bit
        zero_ctrls = [q for q in range(n) if q != p and pattern[q] == 0]
        for q in zero_ctrls:
            qc.x(y[q])
        controls = [ctrl] + [y[q] for q in range(n) if q != p]
        qc.mcx(controls, y[p])
        for q in zero_ctrls:
            qc.x(y[q])
        for q in reversed(others):
            qc.cx(y[p], y[q])

    for i in range(n):
        c = (a * (2 ** i)) % L
        if c == 0:
            continue
        f = [((v + c) % L) if v < L else v for v in range(N)]
        visited = [False] * N
        for s in range(N):
            if visited[s] or f[s] == s:
                visited[s] = True
                continue
            cycle = []
            cur = s
            while not visited[cur]:
                visited[cur] = True
                cycle.append(cur)
                cur = f[cur]
            v0 = cycle[0]
            for k in range(1, len(cycle)):
                transposition(x[i], v0, cycle[k])

    return qc

