        qft()
        for j in range(n):
            theta = 2 * math.pi * k / 2 ** (j + 1)
            qc.cp(theta, ctrl, y[j])
        iqft()

    def ctransp(ctrl, u, v):
        # controlled swap of basis states |u> and |v> on register y
        if u == v:
            return
        d = u ^ v
        p = (d & -d).bit_length() - 1
        others = [q for q in range(n) if q != p and (d >> q) & 1]
        for q in others:
            qc.cx(y[p], y[q])
        zero = []
        for q in range(n):
            if q == p:
                continue
            bit = (u >> q) & 1
            if (d >> q) & 1:
                bit ^= (u >> p) & 1
            if bit == 0:
                zero.append(q)
        for q in zero:
            qc.x(y[q])
        qc.mcx([ctrl] + [y[q] for q in range(n) if q != p], y[p])
        for q in zero:
            qc.x(y[q])
        for q in reversed(others):
            qc.cx(y[p], y[q])

    for i in range(n):
        c = (a * (2 ** i)) % L
        if c == 0:
            continue
        ctrl = x[i]
        if c <= L - c:
            # ADD_c mod L = T_0 T_1 ... T_{c-1} INC^c  (INC^c applied first)
            cadd(ctrl, c)
            for j in reversed(range(c)):
                ctransp(ctrl, j, (j + L) % N)
        else:
            cc = L - c
            # ADD_c mod L = (INC_L)^{-cc} = INC^{-cc} T_{cc-1} ... T_1 T_0  (T_0 applied first)
            for j in range(cc):
                ctransp(ctrl, j, (j + L) % N)
            cadd(ctrl, -cc)

