def _swap_basis(qc, qs, u, v, n):
    # Swap computational basis states |u> and |v> on qubits qs, leave others fixed.
    d = u ^ v
    if d == 0:
        return
    diff = [j for j in range(n) if (d >> j) & 1]
    k = diff[0]
    others = diff[1:]
    for j in others:
        qc.cx(qs[k], qs[j])
    # after CX, u' has bits: u'_j = u_j ^ u_k for j in others, others unchanged
    u2 = u
    for j in others:
        bit = ((u >> j) & 1) ^ ((u >> k) & 1)
        if bit:
            u2 |= (1 << j)
        else:
            u2 &= ~(1 << j)
    ctrls = [j for j in range(n) if j != k]
    zeros = [j for j in ctrls if ((u2 >> j) & 1) == 0]
    for j in zeros:
        qc.x(qs[j])
    if len(ctrls) == 0:
        qc.x(qs[k])
    else:
        qc.mcx([qs[j] for j in ctrls], qs[k])
    for j in zeros:
        qc.x(qs[j])
    for j in reversed(others):
        qc.cx(qs[k], qs[j])


