    # clean ancillas: upper m+1 qubits of y (value fits in lower m bits)
    anc = [y[j] for j in range(m, 2 * m + 1)]

    def c3x_dirty(c0, c1, c2, t, d):
        # X on t controlled by c0,c1,c2 using dirty ancilla d (restored)
        qc.ccx(c2, d, t)
        qc.ccx(c0, c1, d)
        qc.ccx(c2, d, t)
        qc.ccx(c0, c1, d)

