        if nc == 2:
            for t in targets:
                qc.ccx(controls[0], controls[1], t)
            return
        r = min(len(anc), nc - 2)
        # compute AND chain into ancillas
        qc.ccx(controls[0], controls[1], anc[0])
        for j in range(1, r):
            qc.ccx(anc[j - 1], controls[j + 1], anc[j])
        rem = [anc[r - 1]] + list(controls[r + 1:])
        if len(rem) == 2:
            for t in targets:
