        else:  # len(rem) == 3
            for t in targets:
                c3x_dirty(rem[0], rem[1], rem[2], t, controls[0])
        # uncompute
        for j in reversed(range(1, r)):
            qc.ccx(anc[j - 1], controls[j + 1], anc[j])
        qc.ccx(controls[0], controls[1], anc[0])

    controls = [x[i] for i in range(n)]
