        for i in range(k):
            r = c % (2 ** (i + 1))
            if r == 0:
                continue
            ang = 2 * pi * r / 2 ** (i + 1)
            if not controls:
                qc.p(ang, qs[i])
            elif len(controls) == 1:
                qc.cp(ang, controls[0], qs[i])
            else:
                qc.mcp(ang, list(controls), qs[i])

