        elif len(ctrls) == 2:
            c1, c2 = ctrls
            qc.cp(ang / 2, c2, t)
            qc.cx(c1, c2)
            qc.cp(-ang / 2, c2, t)
            qc.cx(c1, c2)
            qc.cp(ang / 2, c1, t)
        else:
            c1, c2, c3 = ctrls
            qc.cp(ang / 2, c3, t)
            qc.ccx(c1, c2, c3)
            qc.cp(-ang / 2, c3, t)
            qc.ccx(c1, c2, c3)
            mcp(ang / 2, [c1, c2], t)

    def qft(qs):
        k = len(qs)
        for i in range(k - 1, -1, -1):
            qc.h(qs[i])
            for j in range(i - 1, -1, -1):
                qc.cp(pi / 2 ** (i - j), qs[j], qs[i])

    def iqft(qs):
        k = len(qs)
        for i in range(k):
            for j in range(i):
                qc.cp(-pi / 2 ** (i - j), qs[j], qs[i])
            qc.h(qs[i])

    def add_const(qs, c, controls):
        k = len(qs)
        c %= 2 ** k
        if c == 0:
            return
        qft(qs)
        for i in range(k):
            r = c % (2 ** (i + 1))
            if r == 0:
                continue
            mcp(2 * pi * r / 2 ** (i + 1), list(controls), qs[i])
        iqft(qs)

    def modadd(T, c, controls):
        c %= L
        if c == 0:
            return
        F = T + [S]
        K = L - c
        add_const(F, 2 ** m - K, controls)      # S = [t >= K]
        add_const(T, L, controls)                # T = t + c (mod 2^m)
        add_const(T, -L, controls + [S])         # if S: T = t + c - L
        add_const(F, -c, controls)               # clears S
        add_const(T, c, controls)                # T = r

    for i in range(n):
        qc.h(x[i])

    qc.x(P[0])

    for i in range(n):
        c = pow(a, 2 ** i, L)
        if c == 1:
            continue
        cinv = pow(c, -1, L)
        for j in range(m):
            modadd(Q, c * (2 ** j), [x[i], P[j]])
        for j in range(m):
            qc.cx(Q[j], P[j])
            qc.ccx(x[i], P[j], Q[j])
            qc.cx(Q[j], P[j])
        for j in range(m):
            modadd(Q, -cinv * (2 ** j), [x[i], P[j]])

    return qc

