try:
    from qiskit.circuit.library import QFTGate

    def _qft_gate(n: int):
        return QFTGate(n)
except ImportError:  # older Qiskit versions
    from qiskit.circuit.library import QFT

    def _qft_gate(n: int):
        return QFT(n, do_swaps=True).to_gate()


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # The quantum Fourier transform satisfies QFT^2 |k> = |-k mod 2^n>
    # (the "reflection" operator). So applying the QFT twice implements
    # the required oracle exactly, with no multi-controlled gates.
    g = _qft_gate(n)
    qc.append(g, list(range(n)))
    qc.append(g, list(range(n)))
    return qc

from qiskit import QuantumCircuit


def solve(n: int) -> QuantumCircuit:
    # -k mod 2^n : bit i flips iff some lower bit of k is 1.
    # Use n-2 clean ancilla qubits to hold z_i = NOT OR(k_0..k_{i-1})
    # computed with a Toffoli chain (depth n-2), apply with a single
    # layer of CX gates, then uncompute the chain using the *new* bits
    # (valid since OR of the low bits is invariant under the negation).
    if n == 1:
        return QuantumCircuit(1)
    if n == 2:
        qc = QuantumCircuit(2)
        qc.cx(0, 1)
        return qc

    qc = QuantumCircuit(n + (n - 2))

    def anc(i):
        # ancilla holding z_i for i = 2 .. n-1
        return n + (i - 2)

    # Step 0: complement all data bits
    for i in range(n):
        qc.x(i)

    # Step 1: compute z_i = AND_{j<i} NOT k_j into ancillas
    qc.ccx(0, 1, anc(2))
    for i in range(2, n - 1):
        qc.ccx(anc(i), i, anc(i + 1))

    # Step 2: apply flips (all in one layer)
    qc.cx(0, 1)
    for i in range(2, n):
        qc.cx(anc(i), i)

    # Step 3: uncompute using the new bits (complemented)
    for i in range(1, n - 1):
        qc.x(i)
    for i in range(n - 2, 1, -1):
        qc.ccx(anc(i), i, anc(i + 1))
    qc.ccx(0, 1, anc(2))

    # Step 4: restore complemented bits
    for i in range(0, n - 1):
        qc.x(i)

    return qc

from qiskit import QuantumCircuit
import numpy as np


def solve(n: int, m_left: int, k_left: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    # qubit 0 -> a, qubit 1 -> b, qubits 2..n -> c (little-endian)
    c_qubits = list(range(2, n + 1))
    N = 2 ** n

    # Correction on the c = 0 sector (one-dimensional irreps):
    #   need overall Z^{m_left} on q0 and Z^{k_left} on q1 there.
    #   Later an unconditional X^{m_left} is applied to q0, so apply (Z then X)^{m_left} now.
    if m_left == 1 or (k_left % 2 == 1):
        for q in c_qubits:
            qc.x(q)
        if k_left % 2 == 1:
            qc.mcp(np.pi, c_qubits, 1)
        if m_left == 1:
            qc.mcp(np.pi, c_qubits, 0)
            qc.mcx(c_qubits, 0)
        for q in c_qubits:
            qc.x(q)

    # Two-dimensional irreps: apply R^{c * k_left} on q0 (controlled by bits of c)
    for j, q in enumerate(c_qubits):
        e = ((2 ** j) * k_left) % N
        if e != 0:
            theta = 2 * np.pi * e / (2 ** (n - 1))
            qc.crz(theta, q, 0)

    # Then X^{m_left} on q0
    if m_left == 1:
        qc.x(0)

    return qc

