import numpy as np


def solve(n: int, m_left: int, k_left: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    # qubit 0 -> a, qubit 1 -> b, qubits 2..n -> c (little-endian)
    a, b = 0, 1
    c_qubits = list(range(2, n + 1))
    N = 2 ** n

    # X^{m_left} first, then R^{-c k_left}: R^{-ck} X = X R^{ck}
    if m_left == 1:
        qc.x(a)

    # controlled Rz(phi) = CP(phi) on (c_j, a) combined with P(-phi/2) on c_j
    for j, q in enumerate(c_qubits):
        e = ((2 ** j) * k_left) % N
        if e != 0:
            phi = -2 * np.pi * e / (2 ** (n - 1))
            qc.cp(phi, q, a)
            qc.p(-phi / 2, q)

    # c = 0 sector: need Z^{m_left} on a and Z^{k_left} on b
    if m_left == 1 or (k_left % 2 == 1):
        for q in c_qubits:
            qc.x(q)
        if k_left % 2 == 1:
            qc.mcp(np.pi, c_qubits, b)
        if m_left == 1:
            qc.mcx(c_qubits, a)
            qc.mcp(np.pi, c_qubits, a)
        for q in c_qubits:
            qc.x(q)

    return qc

