import numpy as np


def solve(n: int, m_right: int, k_right: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    ctrls = list(range(2, n + 1))
    k0 = k_right % 2

    # Correction for the c = 0 (one-dimensional irreps) sector
    if m_right == 1 or k0 == 1:
        for q in ctrls:
            qc.x(q)
        if k0 == 1:
            qc.mcp(np.pi, ctrls, 1)
        if m_right == 1:
            qc.cz(0, 1)
            qc.mcx(ctrls, 1)
            qc.cz(0, 1)
        for q in ctrls:
            qc.x(q)

    # Right multiplication for c != 0: apply R^{c k_right} X^{m_right} on qubit 1
    if m_right == 1:
        qc.x(1)
    for l in range(n - 1):
        theta = (2 * np.pi * (2 ** l) * k_right / (2 ** (n - 1))) % (4 * np.pi)
        if theta != 0:
            qc.crz(theta, 2 + l, 1)

    return qc

