def solve(n: int, m_right: int, k_right: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    ctrls = list(range(2, n + 1))
    k0 = k_right % 2

    # c != 0 sector: apply (X^{m_r} R^{c k_r})^T = R^{c k_r} X^{m_r} on qubit 1
    if m_right == 1:
        qc.x(1)
    for l in range(n - 1):
        theta = (2 * np.pi * (2 ** l) * k_right / (2 ** (n - 1))) % (4 * np.pi)
        if theta != 0:
            qc.crz(theta, 2 + l, 1)

    # c == 0 sector: undo X on qubit 1, then apply Z_0^{m_r} Z_1^{k_r mod 2}
    if m_right == 1 or k0 == 1:
        for q in ctrls:
            qc.x(q)
        if m_right == 1:
            qc.mcx(ctrls, 1)
            qc.mcp(np.pi, ctrls, 0)
        if k0 == 1:
            qc.mcp(np.pi, ctrls, 1)
        for q in ctrls:
            qc.x(q)

    return qc

