def solve(n: int, m_right: int, k_right: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    ctrls = list(range(2, n + 1))
    nc = n - 1

    # c != 0 sector: apply (X^{m_r} R^{c k_r})^T = R^{c k_r} X^{m_r} on qubit 1
    if m_right == 1:
        qc.x(1)
    for l in range(nc):
        theta = (2 * np.pi * (2 ** l) * k_right / (2 ** nc)) % (4 * np.pi)
        if theta != 0:
            qc.crz(theta, 2 + l, 1)

    # c == 0 sector (open controls): undo X on qubit 1, then Z_0^{m_r} Z_1^{k_r mod 2}
    if m_right == 1:
        qc.append(XGate().control(nc, ctrl_state=0), ctrls + [1])
        qc.append(ZGate().control(nc, ctrl_state=0), ctrls + [0])
    if k_right % 2 == 1:
        qc.append(ZGate().control(nc, ctrl_state=0), ctrls + [1])

    return qc

