    if m_right:
        qc.append(XGate().control(nc, ctrl_state=0), ctrls + [1])
        qc.append(ZGate().control(nc, ctrl_state=0), ctrls + [0])
    if k_odd:
        qc.append(ZGate().control(nc, ctrl_state=0), ctrls + [1])

    return qc

