from qiskit.circuit.library import ZGate
import numpy as np


def solve(n: int, m_right: int, k_right: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    nc = n - 1
    ctrls = list(range(2, n + 1))
    k0 = k_right % 2
    # Z on target only when all control qubits (c register) are |0>
    mcz0 = ZGate().control(nc, ctrl_state=0)

    # c != 0 sector: apply (X^{m_r} R^{c k_r})^T = R^{c k_r} X^{m_r} on qubit 1
    if m_right:
        qc.x(1)
    for l in range(nc):
        theta = (2.0 * np.pi * (2 ** l) * k_right / (2 ** nc)) % (4.0 * np.pi)
        if theta != 0.0:
            qc.crz(theta, 2 + l, 1)

    # c == 0 sector: undo X on qubit 1 (H Z H = X), then Z_0^{m_r} Z_1^{k0}
    if m_right:
        qc.h(1)
        qc.append(mcz0, ctrls + [1])
        qc.h(1)
    if m_right and k0:
        # Z_0 Z_1 = CX_{0->1} Z_1 CX_{0->1}
        qc.cx(0, 1)
        qc.append(mcz0, ctrls + [1])
        qc.cx(0, 1)
    elif m_right:
        qc.append(mcz0, ctrls + [0])
    elif k0:
        qc.append(mcz0, ctrls + [1])

    return qc

from qiskit import QuantumCircuit
import math


def solve(n: int, m_before: int, k_before: int, m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    N = 1 << n
    tb = (k_before - m_before) % N
    ta = (k_after - m_after) % N
    sb = -1 if m_before else 1

    def c(m):
        mp = m ^ m_before ^ m_after
        sbm = -1 if (m_before ^ m) else 1
        return (mp + tb - sb * m + sbm * ta) % N

    c0, c1 = c(0), c(1)
    a0 = (c0 + (1 if m_before else 0)) % N
    d = (c1 - c0) % N
    kq = [i + 1 for i in range(n)]

    if m_before:
        for q in kq:
            qc.x(q)

    # QFT (no swaps)
    for j in range(n - 1, -1, -1):
        qc.h(kq[j])
        for l in range(j - 1, -1, -1):
            qc.cp(math.pi / 2 ** (j - l), kq[l], kq[j])

    # add a0 + m*d in Fourier space
    for j in range(n):
        r = a0 % (1 << (j + 1))
        if r:
            qc.p(2 * math.pi * r / 2 ** (j + 1), kq[j])
        rd = d % (1 << (j + 1))
        if rd:
            qc.cp(2 * math.pi * rd / 2 ** (j + 1), 0, kq[j])

    # inverse QFT
    for j in range(n):
        for l in range(j):
            qc.cp(-math.pi / 2 ** (j - l), kq[l], kq[j])
        qc.h(kq[j])

    if m_before ^ m_after:
        qc.x(0)

    return qc

from qiskit import QuantumCircuit
import math


def _qft(qc, qs):
    n = len(qs)
    for j in range(n - 1, -1, -1):
        qc.h(qs[j])
        for l in range(j):
            qc.cp(math.pi / (1 << (j - l)), qs[l], qs[j])


def _iqft(qc, qs):
    n = len(qs)
    for j in range(n):
        for l in range(j - 1, -1, -1):
            qc.cp(-math.pi / (1 << (j - l)), qs[l], qs[j])
        qc.h(qs[j])


def solve(n: int, m_before: int, k_before: int, m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    N = 1 << n
    ks = list(range(1, n + 1))
    sb = -1 if m_before else 1

    # k' = k_b + sb*k + sb*(-1)^m*k_a ; sb*k = ~k + 1 when m_b = 1
    base = (k_before + (1 if m_before else 0)) % N
    v0 = (base + sb * k_after) % N
    v1 = (base - sb * k_after) % N
    delta = (v1 - v0) % N

    if m_before:
        for q in ks:
            qc.x(q)

    _qft(qc, ks)
    for j in range(n):
        mod = 1 << (j + 1)
        r0 = v0 % mod
        if r0:
            qc.p(2.0 * math.pi * r0 / mod, ks[j])
        rd = delta % mod
        if rd:
            qc.cp(2.0 * math.pi * rd / mod, 0, ks[j])
    _iqft(qc, ks)

    if m_before ^ m_after:
        qc.x(0)

    return qc
